"kind": "propose",
"summary": "The 'api' container is throttled at its CPU limit, causing readiness probe failures. Increasing the CPU limit should alleviate throttling.",
"hypotheses": [
    {"root_cause_class": "cpu_limit_too_low", "summary": "Container 'api' is throttled at 0.5 CPU limit (500m), with 64% throttling ratio and 0.495 usage, causing readiness probe timeouts (ev-container_cpu, ev-target_events).", "supporting": ["ev-container_cpu", "ev-target_events"], "contradicting": [],"missing": [],"status": "supported"},
    {"root_cause_class": "new_version_uses_more_cpu", "summary": "Rollout_recent is false (ev-rollout_history), so new version isn't the cause.", "supporting": ["ev-rollout_history"], "contradicting": [],"missing": [],"status": "supported"},
    {"root_cause_class": "node_cpu_contention", "summary": "No evidence of node CPU contention.", "supporting": [], "contradicting": ["ev-rollout_history"], "missing": ["ev-node_cpu"], "status": "refuted"}
],
"proposal": {
    "capability": "deployment.set-resources",
    "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "search", "uid": "uid-deployment-search"},
    "params": {
        "containers": {
            "api": {
                "limits": {
                    "cpu": "750m"
                }
            }
        }
    },
    "expected_effect": "Raise CPU limit of 'api' container from 500m to 750m to clear throttling (ev-container_cpu).",
    "rationale": "Throttling_data_available is true (ev-container_cpu), cpu_throttled_at_limit and cpu_usage_near_limit are true, and readiness probes fail (ev-target_events). Raising the limit to 1.5x current (750m) should resolve throttling without affecting memory or other containers.",
    "cited_evidence_ids": ["ev-container_cpu", "ev-target_events", "ev-rollout_history"],
    "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_recent"]
}
}
